import React from 'react';
import { useGlobal } from '../context/GlobalContext';
import { Link } from 'react-router-dom'; // Import Link from react-router-dom

const Sidebar = () => {
  const { sidebarActive, closeSidebar, userProfile, logout } = useGlobal();

  const handleLinkClick = () => {
    if (sidebarActive) {
      closeSidebar(); // Close the sidebar when a link is clicked
    }
  };

  return (
    <div className={`side-bar ${sidebarActive ? 'active' : ''}`}>
      <div id="close-btn" onClick={closeSidebar}>
        <i className="fas fa-times"></i>
      </div>
      <div className="profile">
        <img
          src={userProfile.profilePic || 'https://cdn.pixabay.com/photo/2015/10/05/22/37/blank-profile-picture-973460_1280.png'}
          alt="Profile" className='image'
        />
        <h3 className="name">{userProfile ? userProfile.name : 'Guest'}</h3>
        <p className="role">{userProfile ? userProfile.role : 'Visitor'}</p>
        <Link to="/loggedin/myprofile" className="btn" onClick={handleLinkClick}>View Profile</Link>
      </div>
      <nav className="navbar">
        <Link to="/loggedin/" onClick={handleLinkClick}>
          <i className="fas fa-home"></i><span>Home</span>
        </Link>
        <Link to="/loggedin/test/mytestslist" onClick={handleLinkClick}>
          <i class="fa-solid fa-globe"></i><span>Online Test's</span>
        </Link>
        <Link to="/loggedin/test/offline/mytestslist" onClick={handleLinkClick}>
          <i class="fa-solid fa-school"></i><span>Offline Test's</span>
        </Link>
        {userProfile.role === 'student' ?
          <Link to="/loggedin/online/fee/payment" onClick={handleLinkClick}>
            <i class="fa-solid fa-indian-rupee-sign"></i><span>Fee Payment</span>
          </Link> : ''
        }
        {((userProfile && userProfile.role === 'teacher') || (userProfile && userProfile.role === 'admin')) && (
          <>
            <Link to="/loggedin/student/attendance" onClick={handleLinkClick}>
              <i className="fa-solid fa-clipboard-user"></i><span>Student Attendance</span>
            </Link>
            <Link to="/loggedin/create/onlinemcqtest" onClick={handleLinkClick}>
              <i class="fa-solid fa-plus"></i><span>Create Online Test</span>
            </Link>
            <Link to="/loggedin/create/offlinetest" onClick={handleLinkClick}>
              <i class="fa-solid fa-plus"></i><span>Create Offline Test</span>
            </Link>
          </>
        )}
        {userProfile && userProfile.role === 'admin' && (
          <>

            <Link to="/loggedin/staff/attendance" onClick={handleLinkClick}>
              <i class="fa-solid fa-chalkboard-user"></i><span>Staff Attendance</span>
            </Link>

            <Link to="/loggedin/students/list" onClick={handleLinkClick}>
              <i className="fa-solid fa-clipboard-user"></i><span>Students</span>
            </Link>
            <Link to="/loggedin/staff/list" onClick={handleLinkClick}>
              <i className="fas fa-chalkboard-user"></i><span>Staff</span>
            </Link>

            <Link to="/loggedin/register" onClick={handleLinkClick}>
              <i class="fa-solid fa-address-card"></i><span>Registration</span>
            </Link>
          </>
        )}
        <Link to="/loggedin/contact" onClick={handleLinkClick}>
          <i className="fas fa-headset"></i><span>Contact Us</span>
        </Link>

        <button className='custome-btn' onClick={logout}>
          <i className="fa-solid fa-right-from-bracket"></i><span>LogOut</span>
        </button>
      </nav>
    </div>
  );
};

export default Sidebar;
