import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { toast } from 'react-toastify';
import { useGlobal } from '../context/GlobalContext';

function OnlineTest() {
  const { role,API_URL } = useGlobal();

  const { testid } = useParams();
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState([]);
  const [score, setScore] = useState(null);
  const [scorePercentage, setScorePercentage] = useState(null);
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [testDetails, setTestDetails] = useState({});
  const [previousResult, setPreviousResult] = useState(null);
  const [testNotAvailable, setTestNotAvailable] = useState(false);

  const fetchQuestions = async () => {
    setLoading(true);
    try {
      const token = document.cookie
        .split('; ')
        .find(row => row.startsWith('x-auth-token='))
        ?.split('=')[1];

      const response = await fetch(`${API_URL}/api/mcqtest/tests/${testid}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          'x-auth-token': token || '',
        },
      });

      const data = await response.json();

      // Check if student has already taken the test
      if (data.studentMarks) {
        setPreviousResult(data.studentMarks);
      } else {
        const testDate = new Date(data.testDate);
        const today = new Date();
        const isSameDate = today.toLocaleDateString() === testDate.toLocaleDateString();

        if (!isSameDate) {
          setTestNotAvailable(true);
          setTestDetails({
            testDate: testDate.toLocaleDateString(),
          });
        } else {
          setQuestions(data.questions || []);
          setAnswers(Array((data.questions || []).length).fill(null));
          setTestDetails({
            testTitle: data.title,
            testDate: testDate.toLocaleDateString(),
            subject: data.subject,
          });
        }
      }
    } catch (error) {
      console.error("Error fetching questions:", error);
      toast.error("Failed to load questions.");
    } finally {
      setLoading(false);
    }
  };
  useEffect(() => {

    fetchQuestions();
  }, [testid]);

  const handleAnswerChange = (questionIndex, answerIndex) => {
    if (role !== 'student') {
      return setSubmitted(true)
    }
    const newAnswers = [...answers];
    newAnswers[questionIndex] = answerIndex;
    setAnswers(newAnswers);
  };

  const handleSubmit = async () => {
    if (!answers.some(answer => answer !== null)) {
      toast.warning("Please select an answer for at least one question before submitting.");
      return;
    }

    let calculatedScore = 0;
    let totalMarks = 0;

    questions.forEach((question, index) => {
      if (answers[index] === question.correctAnswer) {
        calculatedScore += question.marks;
      }
      totalMarks += question.marks;
    });

    const calculatedPercentage = (calculatedScore / totalMarks) * 100;
    setScore(calculatedScore);
    setScorePercentage(calculatedPercentage);

    const testData = {
      testId: testid,
      testTitle: testDetails.testTitle,
      testDate: testDetails.testDate,
      subject: testDetails.subject,
      answers: questions.map((question, index) => ({
        questionText: question.questionText,
        selectedAnswer: answers[index],
      })),
      // feedback: "Great job on the test!",
    };

    try {
      const token = document.cookie
        .split('; ')
        .find(row => row.startsWith('x-auth-token='))
        ?.split('=')[1];

      const response = await fetch(`${API_URL}/api/studentmarks/marks`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-auth-token': token || '',
        },
        body: JSON.stringify(testData),
      });

      if (!response.ok) throw new Error('Failed to submit test results');

      toast.success("Test submitted successfully!");
      setSubmitted(true);
    } catch (error) {
      console.error("Error submitting test:", error);
      toast.error("Failed to submit test.");
    }
  };

  const styles = {
    container: {
      fontFamily: 'Arial, sans-serif',
      textAlign: 'center',
      padding: '40px',
      background: 'linear-gradient(to bottom right, #5a4d91, #8d44ad)',
      borderRadius: '15px',
      boxShadow: '0 10px 30px rgba(0, 0, 0, 0.3)',
      maxWidth: '800px',
      margin: '40px auto 0 auto',
      color: '#fff',
    },
    header: {
      marginBottom: '20px',
      fontSize: '3em',
      fontWeight: 'bold',
    },
    questionBlock: {
      margin: '20px 0',
      padding: '20px',
      borderRadius: '12px',
      backgroundColor: 'rgba(255, 255, 255, 0.9)',
      boxShadow: '0 8px 25px rgba(0, 0, 0, 0.2)',
      color: '#2c3e50',
    },
    questionText: {
      fontSize: '1.8em',
      marginBottom: '10px',
    },
    option: {
      display: 'block',
      margin: '10px 0',
      fontSize: '1.3em',
      padding: '15px',
      borderRadius: '10px',
      backgroundColor: '#eee',
      color: '#2c3e50',
      cursor: 'pointer',
    },
    optionSelected: {
      backgroundColor: '#6c63ff',
      color: '#fff',
    },
    correctAnswer: {
      backgroundColor: '#e8f8e9',
      border: '2px solid #2ecc71',
    },
    incorrectAnswer: {
      backgroundColor: '#fdecec',
      border: '2px solid #e74c3c',
    },
    button: {
      marginTop: '30px',
      padding: '15px 30px',
      backgroundColor: '#6c63ff',
      color: '#fff',
      border: 'none',
      borderRadius: '10px',
      cursor: 'pointer',
      fontSize: '1.4em',
      boxShadow: '0 6px 12px rgba(0, 0, 0, 0.2)',
      transition: 'background-color 0.3s',
    },
    buttonHover: {
      backgroundColor: '#5a4d91',
    },
    score: {
      marginTop: '20px',
      fontSize: '2.5em',
      color: '#f39c12',
    },
  };

  if (testNotAvailable) {
    return (
      <div style={styles.container}>
        <h1 style={styles.header}>Test Not Available</h1>
        <p style={{ fontSize: '1.4em', color: '#f39c12' }}>
          The test is not available today. Please check the test date.
        </p>
        <p style={{ fontSize: '1.2em' }}>
          Test Date: <strong>{Date(testDetails.testDate)}</strong>
        </p>
      </div>
    );
  }

  if (previousResult) {
    return (
      <div style={styles.container}>
        <h1 style={styles.header}>Test Result</h1>
        <div style={{
          ...styles.questionBlock,
          backgroundColor: 'rgba(255, 255, 255, 0.9)',
          color: '#4b0082',
          padding: '30px',
          boxShadow: '0 15px 30px rgba(0, 0, 0, 0.4)',
        }}>
          <h2 style={{ fontSize: '2.5em', color: '#4b0082', marginBottom: '20px' }}>{previousResult.testTitle}</h2>
          <p style={{ fontSize: '1.4em' }}><strong>Date:</strong> {new Date(previousResult.testDate).toLocaleDateString()}</p>
          <p style={{ fontSize: '1.4em' }}><strong>Subject:</strong> {previousResult.subject}</p>
          <p style={{ fontSize: '1.4em' }}><strong>Score:</strong> {previousResult.marksObtained} / {previousResult.totalMarks}</p>
          <h2 style={styles.score}>
            Percentage: {(previousResult.marksObtained / previousResult.totalMarks * 100).toFixed(2)}%
          </h2>
        </div>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <h1 style={styles.header}>Online Test</h1>
      {loading && <div className="loader-container">
        <div className="loader"></div>
      </div>}
      {!loading && questions.length > 0 ? (
        questions.map((question, index) => (
          <div key={index} style={styles.questionBlock}>
            <h2 style={styles.questionText}>{question.questionText}</h2>
            {question.options.map((option, optIndex) => (
              <label
                key={optIndex}
                style={{
                  ...styles.option,
                  ...(answers[index] === optIndex && styles.optionSelected),
                  ...(submitted &&
                    (optIndex === question.correctAnswer
                      ? styles.correctAnswer
                      : answers[index] === optIndex && styles.incorrectAnswer)),
                }}
              >
                <input
                  type="radio"
                  name={`question-${index}`}
                  value={optIndex}
                  checked={answers[index] === optIndex}
                  onChange={() => handleAnswerChange(index, optIndex)}
                  style={{ marginRight: '10px', cursor: 'pointer' }}
                />
                {option}
              </label>
            ))}
            {submitted && answers[index] !== question.correctAnswer && (
              <p style={{ color: '#e74c3c', fontWeight: 'bold' }}>
                Correct Answer: {question.options[question.correctAnswer]}
              </p>
            )}
          </div>
        ))
      ) : (
        !loading && <p>No questions available.</p>
      )}
      {questions.length > 0 && answers.some(answer => answer !== null) && (
        <>
          {!submitted ?
            <button
              style={styles.button}
              onClick={handleSubmit}
            >
              Submit
            </button> : ''}
          {submitted ? <button
            style={styles.button}
            onClick={fetchQuestions}
          >
            View Result
          </button> : ''
          }
        </>
      )}

    </div>
  );
}

export default OnlineTest;
