import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { useGlobal } from "../context/GlobalContext";


const MarkAttendance = () => {
  const { API_URL } = useGlobal()

  const [batches, setBatches] = useState([]);
  const [students, setStudents] = useState([]);
  const [attendanceData, setAttendanceData] = useState({});
  const [selectedBatch, setSelectedBatch] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');

  const getTokenFromCookies = () => {
    const cookieValue = document.cookie.split('; ').find(row => row.startsWith('x-auth-token='));
    return cookieValue ? cookieValue.split('=')[1] : null;
  };

  const token = getTokenFromCookies();

  const fetchBatches = async () => {
    setLoading(true);
    try {
      const response = await axios.get(`${API_URL}/api/standard/batch`, {
        headers: { 'x-auth-token': token }
      });
      setBatches(response.data);
    } catch (error) {
      console.error("Error fetching batches:", error);
      toast.error('Error fetching batches');
    } finally {
      setLoading(false);
    }
  };

  const fetchPreviousAttendance = async () => {
    setLoading(true);
    try {
      const response = await axios.get(`${API_URL}/api/attendance/all-by-date?batch=${selectedBatch}&date=${date}`, {
        headers: { 'x-auth-token': token }
      });
      const attendanceMap = {};
      response.data.forEach(record => {
        attendanceMap[record.studentName] = record.status;
      });
      setAttendanceData(attendanceMap);
    } catch (error) {
      console.error("Error fetching previous attendance:", error);
      toast.error('Error fetching previous attendance');
    } finally {
      setLoading(false);
    }
  };

  const fetchStudents = async () => {
    setLoading(true);
    try {
      const response = await axios.get(`${API_URL}/api/users/batch/${selectedBatch}/students`, {
        headers: { 'x-auth-token': token }
      });
      setStudents(response.data);
      await fetchPreviousAttendance(); // Fetch previous attendance when students are loaded
    } catch (error) {
      console.error("Error fetching students:", error);
      // toast.error('Error fetching students');
      setStudents([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchBatches();
  }, [token]);

  useEffect(() => {
    if (selectedBatch && date) {
      fetchStudents();
    }
  }, [selectedBatch, date]);

  const handleStatusChange = (studentName, status) => {
    setAttendanceData((prevData) => ({ ...prevData, [studentName]: status }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    const attendanceArray = students
      .filter(student => attendanceData[student.name])
      .map(student => ({
        studentId: student._id,
        status: attendanceData[student.name],
        date: date
      }));

    if (attendanceArray.length === 0) {
      setMessage('Please select attendance status for at least one student.');
      setLoading(false);
      return;
    }

    try {
      await axios.post(`${API_URL}/api/attendance/bulk-mark`, { attendances: attendanceArray }, {
        headers: { 'x-auth-token': token }
      });
      toast.success('Attendance marked successfully!');
      await fetchPreviousAttendance(); // Refresh attendance data after submission
      setMessage('');
    } catch (error) {
      console.error("Error marking attendance:", error);
      toast.error('Error marking attendance');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container mt-5 attendance-container">
      <h2 className="text-center mb-4 title">Mark Student Attendance</h2>

      <form onSubmit={handleSubmit} className="attendance-form">
        <div className="mb-3 date-container">
          <label htmlFor="date" className="form-label">Date:</label>
          <input
            type="date"
            id="date"
            className="form-control date-input"
            value={date}
            onChange={(e) => setDate(e.target.value)}
            required
            disabled={loading} // Disable date selection when loading
            max={new Date().toISOString().split("T")[0]} // Prevents future dates
          />

        </div>

        <div className="mb-3 batch-container">
          <label htmlFor="batch" className="form-label">Select Batch:</label>
          <select
            id="batch"
            className="form-control"
            value={selectedBatch}
            onChange={(e) => setSelectedBatch(e.target.value)}
            required
            disabled={loading} // Disable batch selection when loading
          >
            <option value="">-- Select Batch --</option>
            {batches.map(batch => (
              <option key={batch._id} value={batch._id}>
                {`${batch.standard.name} ( ${batch.name} )`}
              </option>
            ))}
          </select>
        </div>

        {loading ? (
            <div className="loader-container">
            <div className="loader"></div>
          </div>
        ) : students.length > 0 ? (
          <table className="table attendance-table">
            <thead>
              <tr>
                <th>Student ID</th>
                <th>Student Name</th>
                <th>Contact Number</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {students.map((student) => (
                <tr key={student._id}>
                  <td><Link style={{ color: "black" }} to={`/loggedin/profile/${student._id}`}>{student.studentId}</Link></td>
                  <td><Link style={{ color: "black" }} to={`/loggedin/profile/${student._id}`}>{student.name}</Link></td>
                  <td><Link style={{ color: "black" }} to={`tel:${student.personalContactNumber}`}>{student.personalContactNumber}</Link></td>
                  <td className="status-options">
                    <label><input type="radio" name={student.name} value="present" checked={attendanceData[student.name] === 'present'} onChange={() => handleStatusChange(student.name, 'present')} /> Present</label>
                    <label><input type="radio" name={student.name} value="absent" checked={attendanceData[student.name] === 'absent'} onChange={() => handleStatusChange(student.name, 'absent')} /> Absent</label>
                    <label><input type="radio" name={student.name} value="late" checked={attendanceData[student.name] === 'late'} onChange={() => handleStatusChange(student.name, 'late')} /> Late</label>
                    <label><input type="radio" name={student.name} value="Absent(Informed)" checked={attendanceData[student.name] === 'Absent(Informed)'} onChange={() => handleStatusChange(student.name, 'Absent(Informed)')} /> Absent (Informed)</label>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <p>No students available for this batch.</p>
        )}

        <button type="submit" className="btn submit-btn mt-3">Mark Attendance</button>
      </form>

      {message && <p className="mt-3 message">{message}</p>}
      <ToastContainer />

      <style>
        {`
          .loader-container {
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100px;
          }
        `}
      </style>
    </div>
  );
};

export default MarkAttendance;
