import React, { useState } from 'react';
import { useGlobal } from '../context/GlobalContext';
import Cookies from 'js-cookie';
import { RotatingLines } from 'react-loader-spinner'; // Import the loader
import { ToastContainer, toast } from 'react-toastify'; // Import toast components
import 'react-toastify/dist/ReactToastify.css'; // Import toast styles

const Login = () => {
    const { login, setUserProfile, setRole,API_URL } = useGlobal();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false); // New loading state

    const handleLogin = async (e) => {
        e.preventDefault();
        setLoading(true); // Start loading
        try {
            const response = await fetch(`${API_URL}/api/auth/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email, password }),
            });

            const data = await response.json();
            if (response.ok) {
                Cookies.set('x-auth-token', data.token, { expires: 7 / 24 });
                setRole(data.profile.role);
                setUserProfile(data.profile);
                login();
            } else {
                toast.error(data.message || "Invalid credentials"); // Use toast for error
                setError(data.message || "Invalid credentials");
            }
        } catch (err) {
            toast.error("Server error, please try again."); // Use toast for server error
            setError("Server error, please try again.");
        } finally {
            setLoading(false); // End loading
        }
    };

    return (
        <div>
            <section className="form-container">
                <form onSubmit={handleLogin}>
                    <h3>Login Now</h3>
                    {error && <p className="error" style={{ color: 'red' }}>{error}</p>}
                    {loading ? (
                        <div className="loader-container">
                            <div className="loader"></div>
                        </div>
                    ) : (
                        <>
                            <p>Your email <span>*</span></p>
                            <input
                                type="email"
                                name="email"
                                placeholder="Enter your email"
                                required
                                maxLength="50"
                                className="box"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                            />
                            <p>Your password <span>*</span></p>
                            <input
                                type="password"
                                name="password"
                                placeholder="Enter your password"
                                required
                                maxLength="20"
                                className="box"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                            />
                            <input
                                type="submit"
                                value="Login now"
                                className="btn"
                            />
                        </>
                    )}
                </form>
            </section>
            <ToastContainer />
            <style>
                {`
                    .loader-container {
                        display: flex;
                        justify-content: center;
                        align-items: center;
                        height: 100px;
                    }
                `}
            </style>
        </div>
    );
};

export default Login;
