import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { useGlobal } from "../context/GlobalContext";

const StaffAttendance = () => {
  const { API_URL } = useGlobal()

  const [staff, setStaff] = useState([]);
  const [attendanceData, setAttendanceData] = useState({});
  const [date, setDate] = useState(() => {
    const today = new Date();
    return today.toISOString().split('T')[0];
  });
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');

  const getTokenFromCookies = () => {
    const cookieValue = document.cookie.split('; ').find(row => row.startsWith('x-auth-token='));
    return cookieValue ? cookieValue.split('=')[1] : null;
  };

  const token = getTokenFromCookies();

  const fetchStaff = async () => {
    setLoading(true);
    try {
      const response = await axios.get(`${API_URL}/api/users/staff/profiles`, {
        headers: { 'x-auth-token': token }
      });
      setStaff(response.data);
    } catch (error) {
      console.error("Error fetching staff:", error);
      setStaff([]);
    } finally {
      setLoading(false);
    }
  };

  const fetchPreviousAttendance = async (selectedDate) => {
    setLoading(true);
    try {
      const response = await axios.get(`${API_URL}/api/attendance/staff/all-by-date?date=${selectedDate}`, {
        headers: { 'x-auth-token': token }
      });
      const attendanceMap = {};
      response.data.forEach(record => {
        attendanceMap[record.staffName] = record.status;
      });
      setAttendanceData(attendanceMap);
    } catch (error) {
      console.error("Error fetching previous attendance:", error);
      setAttendanceData({});
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (date) {
      fetchStaff();
      fetchPreviousAttendance(date);
    }
  }, [date]);

  const handleStatusChange = (staffName, status) => {
    setAttendanceData((prevData) => ({ ...prevData, [staffName]: status }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    const attendanceArray = staff
      .filter(staff => attendanceData[staff.name])
      .map(staff => ({
        staffId: staff._id,
        status: attendanceData[staff.name],
        date
      }));

    if (attendanceArray.length === 0) {
      setMessage('Please select attendance status for at least one staff member.');
      setLoading(false);
      return;
    }

    try {
      await axios.post(`${API_URL}/api/attendance/staff/bulk-mark`, { attendances: attendanceArray }, {
        headers: { 'x-auth-token': token }
      });
      toast.success('Attendance marked successfully!');

      // Fetch the attendance data again to reflect the latest updates
      await fetchPreviousAttendance(date);

      setMessage('');
    } catch (error) {
      console.error("Error marking attendance:", error);
      toast.error('Error marking attendance');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container mt-5 attendance-container">
      <h2 className="text-center mb-4 title">Mark Staff Attendance</h2>

      <form onSubmit={handleSubmit} className="attendance-form">
        <div className="mb-3 date-container">
          <label htmlFor="date" className="form-label">Date:</label>
          <input
            type="date"
            id="date"
            className="form-control date-input"
            value={date}
            onChange={(e) => setDate(e.target.value)}
            required
            disabled={loading} // Disable date selection when loading
            max={new Date().toISOString().split("T")[0]} // Restricts to dates up to today
          />

        </div>

        {loading ? (
          <div className="loader-container">
            <div className="loader-container">
      <div className="loader"></div>
    </div>
          </div>
        ) : staff.length > 0 && (
          <table className="table attendance-table">
            <thead>
              <tr>
                <th>Staff Name</th>
                <th>Contact Number</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {staff.map((staff) => (
                <tr key={staff._id}>
                  <td>
                    <Link style={{ color: "black" }} to={`/loggedin/profile/${staff._id}`}>{staff.name} ({staff.role})</Link>
                  </td>
                  <td>
                    <Link style={{ color: "black" }} to={`tel:${staff.personalContactNumber}`}>
                      {staff.personalContactNumber}
                    </Link>
                  </td>
                  <td className="status-options">
                    <label>
                      <input
                        type="radio"
                        name={staff.name}
                        value="present"
                        checked={attendanceData[staff.name] === 'present'}
                        onChange={() => handleStatusChange(staff.name, 'present')}
                      />
                      Present
                    </label>
                    <label>
                      <input
                        type="radio"
                        name={staff.name}
                        value="absent"
                        checked={attendanceData[staff.name] === 'absent'}
                        onChange={() => handleStatusChange(staff.name, 'absent')}
                      />
                      Absent
                    </label>
                    <label>
                      <input
                        type="radio"
                        name={staff.name}
                        value="late"
                        checked={attendanceData[staff.name] === 'late'}
                        onChange={() => handleStatusChange(staff.name, 'late')}
                      />
                      Late
                    </label>
                    <label>
                      <input
                        type="radio"
                        name={staff.name}
                        value="Absent(Informed)"
                        checked={attendanceData[staff.name] === 'Absent(Informed)'}
                        onChange={() => handleStatusChange(staff.name, 'Absent(Informed)')}
                      />
                      Absent (Informed)
                    </label>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}

        <button type="submit" className="btn submit-btn mt-3">Mark Attendance</button>
      </form>

      {message && <p className="mt-3 message">{message}</p>}
      <ToastContainer />

      <style>
        {`
          .loader-container {
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100px;
          }
        `}
      </style>
    </div>
  );
};

export default StaffAttendance;
