import { jsPDF } from "jspdf";

// Function to generate and download the hall ticket PDF for multiple tests
export const generateHallTicket = async (tests, userProfile) => {
    const doc = new jsPDF();

    // Set document properties
    doc.setProperties({
        title: "Hall Ticket",
        subject: "Examination",
        author: "Your Coaching Center",
        keywords: "hall ticket, examination, offline test",
        creator: "jsPDF"
    });

    // Header Section
    doc.setFontSize(18);
    doc.setTextColor(255, 255, 255);
    doc.setFillColor(0, 51, 102);  // Blue background
    doc.rect(0, 0, 210, 30, "F");
    doc.text("Examination Hall Tickets - 2024", 105, 15, { align: "center" });

    // Candidate Information Section
    doc.setFontSize(12);
    doc.setTextColor(0, 0, 0);
    doc.setFillColor(220, 230, 241); // Light background color
    doc.rect(10, 35, 190, 30, "F");
    doc.text("Candidate Information", 15, 45);

    // Candidate Details
    doc.setFontSize(10);
    doc.text(`Name: ${userProfile.name}`, 15, 55);
    doc.text(`Father's Name: ${userProfile.fatherName || "N/A"}`, 15, 65);
    doc.text(`Mother's Name: ${userProfile.motherName || "N/A"}`, 15, 75);
    doc.text(`Date of Birth: ${userProfile.dob || "N/A"}`, 15, 85);
    doc.text(`Mobile Number: ${userProfile.mobile || "N/A"}`, 15, 95);
    doc.text(`Address: ${userProfile.address}`, 15, 105);

    // Table Headers for Test Details
    const startY = 115;
    const rowHeight = 10;
    doc.setFillColor(0, 51, 102);
    doc.setTextColor(255, 255, 255);
    doc.rect(10, startY, 190, rowHeight, "F");
    doc.text("Test Title", 15, startY + 7);
    doc.text("Batch", 60, startY + 7);
    doc.text("Subject", 90, startY + 7);
    doc.text("Date", 120, startY + 7);
    doc.text("Start Time", 150, startY + 7);
    doc.text("Duration", 180, startY + 7);

    // Reset text color for table content
    doc.setTextColor(0, 0, 0);

    // Populate each test in the table
    let yPosition = startY + rowHeight;
    tests.forEach((test) => {
        if (yPosition > 280) { // If reaching the bottom of the page, add a new page
            doc.addPage();
            yPosition = 20; // Reset y position on the new page
        }

        doc.rect(10, yPosition, 190, rowHeight);
        doc.text(test.title, 15, yPosition + 7);
        doc.text(test.batch?.name || 'N/A', 60, yPosition + 7);
        doc.text(test.subject, 90, yPosition + 7);
        doc.text(new Date(test.testDate).toLocaleDateString(), 120, yPosition + 7);
        doc.text(test.startTime, 150, yPosition + 7);
        doc.text(`${test.durationMinutes} mins`, 180, yPosition + 7);
        yPosition += rowHeight;
    });

    // Footer for Signature
    yPosition += 20;
    doc.rect(10, yPosition, 190, 30);
    doc.text("Signature of the Candidate", 15, yPosition + 10);
    doc.setFontSize(8);
    doc.text("(To be signed in the presence of the Invigilator)", 15, yPosition + 20);

    // Download the PDF
    doc.save(`Hall_Tickets_${new Date().toISOString().split('T')[0]}.pdf`);
};
