import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { ToastContainer, toast } from 'react-toastify';
import imageCompression from 'browser-image-compression';
import 'react-toastify/dist/ReactToastify.css';
import Select from 'react-select';
import { useGlobal } from "../context/GlobalContext";

const RegistrationForm = ({ isAdmin }) => {
  const { API_URL } = useGlobal()

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [role, setRole] = useState('');
  const [selectedBatch, setSelectedBatch] = useState([]);
  const [teacherBatches, setTeacherBatches] = useState([]);
  const [selectedSubjects, setSelectedSubjects] = useState([]); // New state for selected subjects
  const [profileImageUrl, setProfileImageUrl] = useState('');
  const [personalContactNumber, setPersonalContactNumber] = useState('');
  const [emergencyContactNumber, setEmergencyContactNumber] = useState('');
  const [dateOfBirth, setDateOfBirth] = useState('');
  const [gender, setGender] = useState('');
  const [parentName, setParentName] = useState('');
  const [parentContactNumber, setParentContactNumber] = useState('');
  const [relationshipToGuardian, setRelationshipToGuardian] = useState('');
  const [discount, setDiscount] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [batches, setBatches] = useState([]);
  const [paidFee, setPaidFee] = useState('');
  const [address, setAddress] = useState('');
  const [paymentMethod, setPaymentMethod] = useState('');
  const [salary, setSalary] = useState('');
  const [salaryType, setSalaryType] = useState('');

  const token = document.cookie
    .split('; ')
    .find(row => row.startsWith('x-auth-token='))
    ?.split('=')[1];

  useEffect(() => {
    const fetchBatches = async () => {
      try {
        const response = await axios.get(`${API_URL}/api/standard/batch`, {
          headers: { 'x-auth-token': token || '' },
        });
        setBatches(response.data);
      } catch (error) {
        console.error('Error fetching batches:', error);
        toast.error('Failed to load batches.');
      }
    };

    fetchBatches();
  }, [token]);

  const batchOptions = batches.map((batch) => ({
    value: batch._id,
    label: `${batch.name} (${batch.standard.name})`,
  }));

  // Extract subjects from selected batches
  const getSubjectsFromBatches = () => {
    const selectedBatchObjects = batches.filter((batch) =>
      teacherBatches.includes(batch._id)
    );

    const subjects = selectedBatchObjects.flatMap(
      (batch) => batch.standard.subjects
    );

    // Remove duplicate subjects by converting to Set
    const uniqueSubjects = Array.from(new Set(subjects));

    return uniqueSubjects.map((subject) => ({
      value: subject,
      label: subject,
    }));
  };

  // Handle teacher batch selection
  const handleTeacherBatchSelection = (selectedOptions) => {
    setTeacherBatches(selectedOptions ? selectedOptions.map((option) => option.value) : []);
    setSelectedSubjects([]); // Reset selected subjects when batches change
  };

  // Handle subject selection
  const handleSubjectSelection = (selectedOptions) => {
    setSelectedSubjects(selectedOptions ? selectedOptions.map((option) => option.value) : []);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const data = {
      name,
      email,
      password,
      role,
      profileImage: profileImageUrl,
      personalContactNumber,
      emergencyContactNumber,
      dateOfBirth,
      gender,
      address,
    };

    if (role === 'student') {
      data.batch = selectedBatch;
      data.discount = discount;
      data.parentName = parentName;
      data.parentContactNumber = parentContactNumber;
      data.relationshipToGuardian = relationshipToGuardian;
      data.paidFee = paidFee;
      data.paymentMethod = paymentMethod;
    }

    if (role === 'teacher') {
      data.teacherBatches = teacherBatches;
      data.subjects = selectedSubjects;
    }

    if (role === 'teacher' || role === 'admin') {
      data.salary = salary;
      data.salaryType = salaryType;
    }

    try {
      const response = await axios.post(`${API_URL}/api/auth/register`, data, {
        headers: { 'x-auth-token': token || '' },
      });
      console.log(response.data);
      toast.success("User registered successfully!");

      // Reset fields after registration
      setName('');
      setEmail('');
      setPassword('');
      setConfirmPassword('');
      setRole('');
      setSelectedBatch([]);
      setTeacherBatches([]);
      setSelectedSubjects([]);
      setProfileImageUrl('');
      setPersonalContactNumber('');
      setEmergencyContactNumber('');
      setDateOfBirth('');
      setGender('');
      setParentName('');
      setParentContactNumber('');
      setRelationshipToGuardian('');
      setDiscount('');
      setPaidFee('');
      setAddress('');
      setPaymentMethod('');
      setSalary('');
      setSalaryType('');
    } catch (error) {
      console.error('Error registering user:', error);
      toast.error("Failed to register user.");
    }
  };

  const isFormIncomplete =
    !name || !email || !password || !confirmPassword ||
    !role || !emergencyContactNumber ||
    (role === 'student' && (
      !selectedBatch || !parentContactNumber ||
      !address || password !== confirmPassword
    )) ||
    (role === 'teacher' && teacherBatches.length === 0);
    const handleFileChange = async (e) => {
      const file = e.target.files[0];
      if (!file) return;
    
      try {
        // Set image compression options to try and reduce the size to ~7 KB
        const options = {
          maxSizeMB: 0.001, // Target a very small file size, e.g., 1 KB (adjust if needed)
          maxWidthOrHeight: 200, // Reduce dimensions to control file size
          useWebWorker: true, // Use web worker for faster compression
        };
    
        // Compress the image
        const compressedFile = await imageCompression(file, options);
    
        // Check the compressed file size (in bytes)
        if (compressedFile.size > 7000) {
          // If the file is still too large, further reduce the quality or size
          const moreCompressionOptions = {
            ...options,
            maxSizeMB: 0.001, // Further reduce size if necessary
            maxWidthOrHeight: 150, // Further reduce dimensions if necessary
          };
    
          const furtherCompressedFile = await imageCompression(file, moreCompressionOptions);
          const reader = new FileReader();
          reader.onload = () => {
            setProfileImageUrl(reader.result); // Update state with the compressed image URL
          };
          reader.readAsDataURL(furtherCompressedFile);
        } else {
          // If the file is small enough, proceed as usual
          const reader = new FileReader();
          reader.onload = () => {
            setProfileImageUrl(reader.result); // Update state with the compressed image URL
          };
          reader.readAsDataURL(compressedFile);
        }
      } catch (error) {
        console.error("Error uploading image:", error);
        toast.error("Failed to upload image.");
      }
    };
  if (!isAdmin) return <p>You do not have permission to register users.</p>;

  return (
    <section className="form-container">
      <ToastContainer />
      <form onSubmit={handleSubmit}>
        <h3>Register Now</h3>
        <p>Name <span>*</span></p>
        <input type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="Enter name" required maxLength="50" className="box" />
        <p>Select Profile Pic<span>*</span></p>
        <div style={{ display: 'flex' }}>

          <label htmlFor="fileInput" className="custom-file-upload">
            Choose Picture
          </label>
          <input
            type="file"
            id="fileInput"
            accept="image/*"
            onChange={handleFileChange}
            required
            className="file-input-hidden"
          />
          &nbsp;&nbsp;&nbsp;&nbsp;
          {profileImageUrl!=='' ?
            <>
              <img src={profileImageUrl} height={50} alt="profile" />
              <button className="img-remove" onClick={() => setProfileImageUrl("")}><i class="fa-solid fa-trash"></i></button>
            </>
            : ""
          }
        </div>

        <p>Email <span>*</span></p>
        <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="Enter email" required maxLength="50" className="box" />

        <p>Password <span>*</span></p>
        <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Enter password" required maxLength="20" className="box" />

        <p>Confirm Password <span>*</span></p>
        <input type="password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} placeholder="Confirm password" required maxLength="20" className="box" />

        {/* Role Selection */}
        <p>Select Role <span>*</span></p>
        <select value={role} onChange={(e) => setRole(e.target.value)} required className="box">
          <option value="">Select Role</option>
          <option value="admin">Admin</option>
          <option value="teacher">Teacher</option>
          <option value="student">Student</option>
        </select>

        {role === 'student' && (
          <>
            <p>Select Batch <span>*</span></p>
            <select value={selectedBatch} onChange={(e) => setSelectedBatch(e.target.value)} required className="box">
              <option value="">Select Batch</option>
              {batches.map(batch => (
                <option key={batch._id} value={batch._id}>{batch.name} ({batch.standard.name})</option>
              ))}
            </select>
          </>
        )}
        {role === 'teacher' && (
          <>
            <p>Select Batches <span>*</span></p>
            <Select
              options={batchOptions}
              isMulti
              value={batchOptions.filter(option => teacherBatches.includes(option.value))}
              onChange={handleTeacherBatchSelection}
              placeholder="Search and select batches..."
              className="multi-select-dropdown"
              closeMenuOnSelect={false}
            />
            <p>Select Subjects <span>*</span></p>
            <Select
              options={getSubjectsFromBatches()}
              isMulti
              value={getSubjectsFromBatches().filter(option => selectedSubjects.includes(option.value))}
              onChange={handleSubjectSelection}
              placeholder="Select subjects..."
              className="multi-select-dropdown"
              closeMenuOnSelect={false}
            />
          </>
        )}
        <p>Personal Contact Number</p>
        <input type="number" value={personalContactNumber} onChange={(e) => setPersonalContactNumber(e.target.value)} placeholder="Enter personal number" className="box" />

        <p>Emergency Contact Number <span>*</span></p>
        <input type="number" value={emergencyContactNumber} onChange={(e) => setEmergencyContactNumber(e.target.value)} placeholder="Enter emergency number" required className="box" />

        <p>Date of Birth</p>
        <input
          type="date"
          value={dateOfBirth}
          onChange={(e) => setDateOfBirth(e.target.value)}
          className="box"
          max={new Date().toISOString().split("T")[0]} // Prevents future dates
        />
        <p>Gender</p>
        <select value={gender} onChange={(e) => setGender(e.target.value)} className="box">
          <option value="">Select Gender</option>
          <option value="male">Male</option>
          <option value="female">Female</option>
          <option value="other">Other</option>
        </select>

        {role === 'student' && (
          <>
            <p>Parent's Name</p>
            <input type="text" value={parentName} onChange={(e) => setParentName(e.target.value)} placeholder="Enter parent's name" className="box" />

            <p>Parent's Contact Number <span>*</span></p>
            <input type="number" value={parentContactNumber} onChange={(e) => setParentContactNumber(e.target.value)} placeholder="Enter parent's contact number" required className="box" />

            <p>Relationship to Guardian</p>
            <input type="text" value={relationshipToGuardian} onChange={(e) => setRelationshipToGuardian(e.target.value)} placeholder="Enter relationship to guardian" className="box" />
          </>
        )}

        {role === 'student' && (
          <>
            <p>Discount Amount</p>
            <input type="number" value={discount} onChange={(e) => setDiscount(e.target.value)} placeholder="Enter discount amount" className="box" />
          </>
        )}

        <p>Address <span>*</span></p>
        <input type="text" value={address} onChange={(e) => setAddress(e.target.value)} placeholder="Enter address" required maxLength="150" className="box" />

        {role !== 'student' && (
          <>
            <p>Salary</p>
            <input type="number" value={salary} onChange={(e) => setSalary(e.target.value)} placeholder="Enter salary" className="box" />

            <p>Salary Type <span>*</span></p>
            <select value={salaryType} onChange={(e) => setSalaryType(e.target.value)} required className="box">
              <option value="">Select Salary Type</option>
              <option value="monthly">Monthly</option>
              <option value="daily">Daily</option>
            </select>
          </>
        )}

        {role === 'student' && (
          <>
            <p>Paid Fee</p>
            <input type="number" value={paidFee} onChange={(e) => setPaidFee(e.target.value)} placeholder="Enter paid fee" className="box" />

            <p>Payment Method <span>*</span></p>
            <select value={paymentMethod} onChange={(e) => setPaymentMethod(e.target.value)} required className="box">
              <option value="">Select Payment Method</option>
              <option value="cash">Cash</option>
              <option value="card">Card</option>
              <option value="bank_transfer">Bank Transfer</option>
              <option value="UPI">UPI</option>
            </select>
          </>
        )}


        <input
          type="submit"
          value="Register New"
          className="btn"
          disabled={isFormIncomplete || isUploading}
          style={{ backgroundColor: (isFormIncomplete || isUploading) ? 'grey' : '' }}
        />
      </form>
    </section>
  );
};

export default RegistrationForm;
