import React, { useEffect, useState } from 'react';
import { Routes, Route, Navigate, useNavigate } from 'react-router-dom';

import Header from './components/Header';
import Sidebar from './components/Sidebar';
import DashBoard from './pages/Dashboard';
import Courses from './components/Courses';
import Footer from './components/Footer';
import Login from './pages/Login';
import MyProfile from './pages/MyProfile';
import Profile from './pages/Profile';
import { useGlobal } from './context/GlobalContext';
import Register from './pages/Register';
import MarkStudentAttendance from './pages/MarkStudentAttendance';
import MarkStaffAttendance from './pages/MarkStaffAttendance';
import './style.css';
import Cookies from 'js-cookie';
import StudentListByBatch from './pages/StudentsList';
import StaffListByRole from './pages/StaffList';
import ManageBatches from './pages/ManageBatches';
import StudentAttendanceHistory from './pages/StudentAttandanceHistory';
import StaffAttendanceHistory from './pages/StaffAttandanceHistory';
import FeePaymentHistory from './pages/FeePaymentHistory';
import AccessDenied from './pages/AccessDenied';
import PageNotFound404 from './pages/PageNotFound404';
import OnlineMCQTest from './pages/OnlineMCQTest';
import OnlineTestForm from './pages/OnlineTestForm';
import OfflineTestForm from './pages/OfflineTestForm';
import OnlinetestsList from './pages/OnlineTestsList';
import OfflinetestsList from './pages/OfflineTestsList';
import TestsResults from './pages/TestsResults';
import BulkAddStudentMarks from './pages/AddStudentMarksForm';
import OnlineFeePayment from './pages/OnlineFeePayment'
const App = () => {
  const navigate = useNavigate();
  const { isLoggedIn, isLoading, role } = useGlobal(); // Change loading to isLoading
  const [darkMode, setDarkMode] = useState(localStorage.getItem('dark-mode') === 'enabled');
  const [sidebarActive, setSidebarActive] = useState(false);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 768 && sidebarActive) {
        setSidebarActive(false);
      }
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [sidebarActive]);

  useEffect(() => {
    document.body.classList.toggle('dark', darkMode);
  }, [darkMode]);

  const toggleDarkMode = () => {
    const updatedDarkMode = !darkMode;
    setDarkMode(updatedDarkMode);
    localStorage.setItem('dark-mode', updatedDarkMode ? 'enabled' : 'disabled');
  };

  const toggleSidebar = () => {
    setSidebarActive(prev => !prev);
  };

  const closeSidebar = () => {
    setSidebarActive(false);
  };

  const token = Cookies.get('x-auth-token');
  useEffect(() => {
    if (token === undefined) {
      navigate('/login');
    }
  }, [token, navigate]);

  // Show loader if data is being fetched
  if (isLoading) {
    return <div style={{ textAlign: 'center', marginTop: '50px' }}><h1>Loading...</h1></div>;
  }

  // Check if the current path should show the AccessDenied page
  const restrictedPaths = ['/student/attendance', '/staff/attendance'];
  const currentPath = window.location.pathname;
  const showAccessDenied = role === 'student' && restrictedPaths.includes(currentPath);

  if (showAccessDenied) {
    // Render the AccessDenied page in full screen
    return <AccessDenied />;
  }

  return (
    <div>
      {isLoggedIn && (
        <>
          <Header toggleDarkMode={toggleDarkMode} darkMode={darkMode} toggleSidebar={toggleSidebar} />
          <Sidebar isActive={sidebarActive} closeSidebar={closeSidebar} />
        </>
      )}

      <Routes>
        <Route path="/loggedin" element={<DashBoard />} />
        <Route path="/loggedin/courses" element={<Courses />} />
        <Route path="/loggedin/student/attendance/:studentId" element={<StudentAttendanceHistory />} />
        <Route path="/loggedin/staff/attendance/:staffId" element={<StaffAttendanceHistory />} />
        <Route path="/loggedin/student/feepayments/:studentId" element={<FeePaymentHistory />} />

        {/* Restricted attendance routes for students */}
        <Route path="/loggedin/student/attendance" element={(role === 'student') ? <AccessDenied /> : <MarkStudentAttendance />} />
        <Route path="/loggedin/staff/attendance" element={(role === 'student' || role === 'teacher') ? <AccessDenied /> : <MarkStaffAttendance />} />

        {/* Admin and other routes */}
        <Route path="/loggedin/students/list" element={<StudentListByBatch />} />
        <Route path="/loggedin/staff/list" element={<StaffListByRole />} />
        <Route path="/loggedin/register" element={role === 'admin' ? <Register isAdmin={role === 'admin'} /> : <AccessDenied />} />
        <Route path="/loggedin/myprofile" element={<MyProfile />} />
        <Route path="/loggedin/profile/:id" element={<Profile />} />
        <Route path="/loggedin/manage-batches/:teacherId" element={<ManageBatches />} />
        <Route path="/loggedin/onlinetest/:testid" element={<OnlineMCQTest />} />
        <Route path="/loggedin/create/onlinemcqtest" element={<OnlineTestForm />} />
        <Route path="/loggedin/create/offlinetest" element={<OfflineTestForm />} />
        <Route path="/loggedin/test/mytestslist" element={<OnlinetestsList />} />
        <Route path="/loggedin/test/offline/mytestslist" element={<OfflinetestsList />} />
        <Route path="/loggedin/test/addStudentmarks/:testId" element={<BulkAddStudentMarks />} />
        <Route path="/loggedin/test/TestsResults/:testid" element={<TestsResults />} />
        <Route path="/loggedin/online/fee/payment" element={<OnlineFeePayment />} />
        <Route path="/login" element={isLoggedIn ? <Navigate to="/loggedin/" /> : <Login />} />

        {/* Fallback route for unmatched URLs */}
        {/* <Route path="*" element={<PageNotFound404 />} /> */}
      </Routes>

      {/* {isLoggedIn && <Footer />} */}
    </div>
  );
};

export default App;
