import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { useGlobal } from '../context/GlobalContext';
import UpdateProfileForm from '../components/UpdateProfileForm'; // Import the new component
import axios from 'axios';

const Profile = () => {
  const { userProfile,API_URL } = useGlobal();
  const [isEditing, setIsEditing] = useState(false);
  const [passwordData, setPasswordData] = useState({ currentPassword: '', newPassword: '', confirmNewPassword: '' });
  const [updateSuccess, setUpdateSuccess] = useState(null);
  const [passwordChangeSuccess, setPasswordChangeSuccess] = useState(null);
  const [error, setError] = useState(null);

  if (!userProfile) {
    return             <div className="loader-container">
    <div className="loader"></div>
  </div>;
  }

  // Handle form submission for password change
  const handlePasswordChangeSubmit = async (e) => {
    e.preventDefault();
    if (passwordData.newPassword !== passwordData.confirmNewPassword) {
      setError('New passwords do not match');
      return;
    }
    try {
      await axios.post(`${API_URL}/api/users/profile/${userProfile._id}`, passwordData);
      setPasswordChangeSuccess('Password changed successfully');
      setPasswordData({ currentPassword: '', newPassword: '', confirmNewPassword: '' });
    } catch (error) {
      setError('Failed to change password');
    }
  };

  // Extract attendanceCounts from userProfile
  const attendanceCounts = userProfile.attendanceCounts || {
    present: 0,
    absent: 0,
    late: 0,
    "Absent(Informed)": 0,
  };

  // Calculate total attendance
  const totalAttendance =
    attendanceCounts.present +
    attendanceCounts.absent +
    attendanceCounts.late +
    attendanceCounts["Absent(Informed)"];

  // Calculate present percentage considering late and Absent(Informed) as present
  const presentPercentage = totalAttendance
    ? (((attendanceCounts.present + attendanceCounts.late + attendanceCounts["Absent(Informed)"]) / totalAttendance) * 100).toFixed(2)
    : 0;

  return (
    <section className="user-profile">
      <h1 className="heading">Your Profile</h1>

      {isEditing ? (
        <UpdateProfileForm
          userProfile={userProfile}
          userId={userProfile._id}
          onClose={() => setIsEditing(false)}
          onUpdateSuccess={setUpdateSuccess}
          isAdmin={userProfile.role==='admin'}
        />
      ) : (
        <div className="info">
          <div className="user">
            <img
              src={userProfile.profilePic || 'https://cdn.pixabay.com/photo/2015/10/05/22/37/blank-profile-picture-973460_1280.png'}
              alt="Profile"
            />
            <h3>{userProfile.name}</h3>
            <p>Role: {userProfile.role}</p>
            <p>Gender: {userProfile.gender}</p>
            <p>Date of Birth: {new Date(userProfile.dateOfBirth).toLocaleDateString()}</p>
            {userProfile.role === 'admin' && (
              <button onClick={() => setIsEditing(true)} className="inline-btn">
                <i className="fa-solid fa-pen-to-square"></i> Edit Profile
              </button>
            )}
          </div>

          <div className="box-container">
            {userProfile.role === 'student' && (
              <div className="box">
                <div className="flex">
                  <i className="fa-solid fa-book"></i>
                  <div>
                    <span>{userProfile.batch?.name}</span>
                    <p>{userProfile.batch?.standard?.name}</p>
                  </div>
                </div>
              </div>
            )}

            {userProfile.role === 'student' ? (
              <div className="box">
                <div className="flex">
                  <i className="fa-solid fa-wallet"></i>
                  <div>
                    <span>Fees</span>
                    <p>Total: ₹{userProfile.totalFee}</p>
                    <p>Pending: ₹{userProfile.pendingFee}</p>
                    <p>Discount: ₹{userProfile.discount}</p>
                  </div>
                </div>
                <Link to={`/loggedin/student/feepayments/${userProfile._id}`} className="inline-btn">
                  View Transactions
                </Link>
              </div>
            ) : (
              userProfile.role !== 'student' && (
                <div className="box">
                  <div className="flex">
                    <i className="fa-solid fa-indian-rupee-sign"></i>
                    <div>
                      <span>Salary</span>
                      <p>Amount: ₹{userProfile.salary}</p>
                      <p>Type: {userProfile.salaryType}</p>
                    </div>
                  </div>
                  <Link to="/loggedin/salary-details" className="inline-btn">
                    View Salary Details
                  </Link>
                </div>
              )
            )}

            <div className="box">
              <div className="flex">
                <i className="fa-solid fa-phone"></i>
                <div>
                  <span>Contact</span>
                  <p>Personal: {userProfile.personalContactNumber}</p>
                  <p>Emergency: {userProfile.emergencyContactNumber}</p>
                </div>
              </div>
            </div>

            <div className="box">
              <div className="flex">
                <i className="fas fa-calendar-check"></i>
                <div>
                  <span>{presentPercentage}%</span>
                  <p>Attendance</p>
                </div>
              </div>
              <Link to={`/loggedin/${userProfile.role === 'student' ? 'student' : "staff"}/attendance/${userProfile._id}`} className="inline-btn">
                View Attendance
              </Link>
            </div>

            {userProfile.role === 'student' && (
              <div className="box">
                <div className="flex">
                  <i className="fa-solid fa-user-group"></i>
                  <div>
                    <span>Guardian</span>
                    <p>Name: {userProfile.parentName}</p>
                    <p>Relation: {userProfile.relationshipToGuardian}</p>
                    <p>Contact: {userProfile.parentContactNumber}</p>
                  </div>
                </div>
              </div>
            )}

            {userProfile.role === 'teacher' && (
              <div className="box">
                <div className="flex">
                  <i className="fas fa-chalkboard-teacher"></i>
                  <div>
                    <p>My batches</p>
                  </div>
                </div>
                <Link to={`/loggedin/manage-batches/${userProfile._id}`} className="inline-btn">
                  View Batches
                </Link>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Display success or error messages */}
      {updateSuccess && <p className="success">{updateSuccess}</p>}
      {error && <p className="error">{error}</p>}
    </section>
  );
};

export default Profile;
