import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams, useNavigate } from 'react-router-dom';
import { useGlobal } from "../context/GlobalContext";

const BulkAddStudentMarks = () => {
  const { API_URL } = useGlobal()

  const { testId } = useParams(); // Get testId from URL parameters
  const navigate = useNavigate(); // Initialize navigate hook
  const [students, setStudents] = useState([]);
  const [testDetails, setTestDetails] = useState(null);
  const [records, setRecords] = useState([]);
  const [totalMark, setTotalMark] = useState();
  const [loading, setLoading] = useState(false); // Loader state

  useEffect(() => {
    // Fetch the test details using the testId
    const fetchTestAndStudents = async () => {
      try {
        const testResponse = await axios.get(`${API_URL}/api/offline/tests/${testId}`, {
          headers: {
            'x-auth-token': document.cookie.split('x-auth-token=')[1], // Assuming token is stored in cookies
          },
        });
        const testData = testResponse.data;
        setTestDetails(testData);

        const { batch, totalMarks } = testData;
        setTotalMark(totalMarks);

        const studentsResponse = await axios.get(`${API_URL}/api/users/batch/${batch}/students`, {
          headers: {
            'x-auth-token': document.cookie.split('x-auth-token=')[1],
          },
        });

        setStudents(studentsResponse.data);

        const initialRecords = studentsResponse.data.map((student) => ({
          studentId: student._id,
          marksObtained: '',
          feedback: '',
        }));
        setRecords(initialRecords);
      } catch (error) {
        console.error('Error fetching test or students:', error);
      }
    };

    fetchTestAndStudents();
  }, [testId]);

  const handleInputChange = (index, event) => {
    const { name, value } = event.target;
    const values = [...records];

    if (name === 'marksObtained') {
      const numericValue = Number(value);
      if (numericValue > totalMark) {
        alert(`Marks obtained cannot be greater than the total marks (${totalMark}).`);
        return;
      }
      values[index][name] = numericValue;
    } else {
      values[index][name] = value;
    }

    setRecords(values);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true); // Set loading to true
    try {
      const response = await axios.post(
        `${API_URL}/api/studentmarks/bulk/marks/${testId}`,
        { records },
        {
          headers: {
            'x-auth-token': document.cookie.split('x-auth-token=')[1],
          },
        }
      );
      alert('Marks added successfully!');
      console.log(response.data);
      navigate(`/loggedin/test/TestsResults/${testId}`);
    } catch (error) {
      console.error('Failed to add marks:', error);
      alert('Failed to add marks!');
    } finally {
      setLoading(false); // Set loading to false
    }
  };

  return (
    <div className="addstudentmarks">
      {testDetails ? (
        <h1>Bulk Add Student Marks for Test: {testDetails.title}</h1>
      ) : (
        <h1>Loading Test Details...</h1>
      )}

      {loading ? (
            <div className="loader-container">
            <div className="loader"></div>
          </div>
      ) : (
        <form onSubmit={handleSubmit}>
          {students.map((student, index) => (
            <div key={index} className="record">
              <p>{student.name} (ID: {student._id})</p>

              <input
                type="number"
                name="marksObtained"
                placeholder="Marks Obtained"
                value={records[index].marksObtained}
                onChange={(event) => handleInputChange(index, event)}
                required
              />

              <input type="number" name="totalMarks" value={totalMark} disabled />

              <textarea
                name="feedback"
                placeholder="Feedback"
                value={records[index].feedback}
                onChange={(event) => handleInputChange(index, event)}
              />
            </div>
          ))}
          <button type="submit" disabled={loading}>Submit Marks</button>
        </form>
      )}
    </div>
  );
};

export default BulkAddStudentMarks;
