import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import Cookies from 'js-cookie';
import { useGlobal } from '../context/GlobalContext';

// BatchCard component to display each batch
const BatchCard = ({ batch, onUpdate, onDelete, isAdmin }) => {
  return (
    <div className="batch-card">
      <h2 className="batch-name">{batch.name}</h2>
      <p className="batch-standard">Standard: {batch.standard.name}</p>
      <p className="batch-time">Time: {batch.startTime} - {batch.endTime}</p>
      
      {isAdmin && (
        <div className="button-container">
          <button className="update-button" onClick={() => onUpdate(batch)}>Update</button>
          <button className="delete-button" onClick={() => onDelete(batch)}>
            <i className="fas fa-trash"></i>
          </button>
        </div>
      )}
    </div>
  );
};

// BatchList component to fetch and display the list of batches
const BatchList = () => {
  const { role,API_URL } = useGlobal(); // Role is provided by global context
  const { teacherId } = useParams(); // Retrieve teacherId from route parameters (for admins)
  const [batches, setBatches] = useState([]);
  const [loading, setLoading] = useState(true); // New loading state

  useEffect(() => {
    // Function to fetch batches from the server
    const fetchBatches = async () => {
      setLoading(true); // Start loading
      try {
        const token = Cookies.get('x-auth-token'); // Extract token from cookies
        if (!token) {
          console.error('No token found');
          return;
        }

        // Determine the endpoint based on the user's role
        const endpoint = role === 'admin' 
          ? `${API_URL}/api/users/batches/${teacherId}`
          : `${API_URL}/api/users/batches/${teacherId || ''}`; // For teachers, teacherId is not required

        const response = await axios.get(endpoint, {
          headers: {
            'x-auth-token': token, // Set token in the request header
          }
        });

        // Update batches state
        setBatches(response.data.teacherBatches || []);
      } catch (error) {
        console.error('Error fetching batches:', error);
      } finally {
        setLoading(false); // End loading
      }
    };

    fetchBatches();
  }, [teacherId, role]);

  const handleUpdate = (batch) => {
    console.log("Updating batch:", batch);
  };

  const handleDelete = (batch) => {
    console.log("Deleting batch:", batch);
  };

  return (
    <div className="batch-list">
      {loading ? ( // Show loader if loading
            <div className="loader-container">
            <div className="loader"></div>
          </div>
      ) : (
        batches.map((batch, index) => (
          <BatchCard 
            key={index} 
            batch={batch} 
            onUpdate={handleUpdate} 
            onDelete={handleDelete} 
            isAdmin={role === 'admin'} // Pass isAdmin prop to control button visibility
          />
        ))
      )}
    </div>
  );
};

export default BatchList;
