import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Toastify from 'toastify-js';
import "toastify-js/src/toastify.css"; // Import Toastify CSS
import { useGlobal } from "../context/GlobalContext";

function TestPaperForm() {
    const { API_URL } = useGlobal()

    // const { userProfile } = useGlobal();

    const [title, setTitle] = useState('');
    const [batch, setBatch] = useState('');
    const [testDate, setTestDate] = useState('');
    const [batches, setBatches] = useState([]);
    const [subjects, setSubjects] = useState([]);
    const [subject, setSubject] = useState('');
    const [questions, setQuestions] = useState([{ questionText: '', options: ['', '', '', ''], correctAnswer: '', marks: 1 }]);
    const [loading, setLoading] = useState(false); // Loading state

    useEffect(() => {
        const fetchBatches = async () => {
            try {
                const authToken = document.cookie
                    .split('; ')
                    .find((row) => row.startsWith('x-auth-token='))?.split('=')[1];

                if (!authToken) {
                    alert('Auth token not found. Please log in.');
                    return;
                }

                const response = await axios.get(`${API_URL}/api/standard/batch`, {
                    headers: {
                        'Content-Type': 'application/json',
                        'x-auth-token': authToken,
                    },
                });
                setBatches(response.data);
            } catch (error) {
                console.error('Error fetching batches:', error);
                alert('Failed to fetch batches. Please try again.');
            }
        };

        fetchBatches();
    }, []);

    const handleBatchChange = (e) => {
        const selectedBatchId = e.target.value;
        setBatch(selectedBatchId);

        const selectedBatch = batches.find((batch) => batch._id === selectedBatchId);
        setSubjects(selectedBatch ? selectedBatch.standard.subjects : []);
    };

    const handleQuestionChange = (index, event) => {
        const newQuestions = [...questions];
        newQuestions[index].questionText = event.target.value;
        setQuestions(newQuestions);
    };

    const handleOptionChange = (questionIndex, optionIndex, event) => {
        const newQuestions = [...questions];
        newQuestions[questionIndex].options[optionIndex] = event.target.value;
        setQuestions(newQuestions);
    };

    const handleCorrectAnswerChange = (questionIndex, event) => {
        const newQuestions = [...questions];
        newQuestions[questionIndex].correctAnswer = parseInt(event.target.value, 10);
        setQuestions(newQuestions);
    };

    const handleMarksChange = (questionIndex, event) => {
        const newQuestions = [...questions];
        newQuestions[questionIndex].marks = parseInt(event.target.value, 10);
        setQuestions(newQuestions);
    };

    const addQuestion = () => {
        setQuestions([...questions, { questionText: '', options: ['', '', '', ''], correctAnswer: '', marks: 1 }]);
    };

    const deleteQuestion = (index) => {
        const newQuestions = questions.filter((_, questionIndex) => questionIndex !== index);
        setQuestions(newQuestions);
    };

    const handleSubmit = async (event) => {
        event.preventDefault();
        if(questions.length===0) {
            return ''
        }
        else{

            setLoading(true); // Set loading to true
            
            const testPaper = {
            title,
            batch,
            subject,
            questions: questions.map((q) => ({
                questionText: q.questionText,
                options: q.options,
                correctAnswer: q.correctAnswer,
                marks: q.marks,
            })),
            testDate: new Date(testDate).toISOString(),
        };
        
        try {
            const authToken = document.cookie
                .split('; ')
                .find((row) => row.startsWith('x-auth-token='))?.split('=')[1];

            if (!authToken) {
                alert('Auth token not found. Please log in.');
                return;
            }
            
            const response = await axios.post(`${API_URL}/api/mcqtest/tests/createMCQTest`, testPaper, {
                headers: {
                    'Content-Type': 'application/json',
                    'x-auth-token': authToken,
                },
            });

            Toastify({
                text: "Test paper created successfully!",
                duration: 3000,
                gravity: "top",
                position: 'center',
                backgroundColor: "#4caf50",
            }).showToast();
        } catch (error) {
            console.error('Error creating test paper:', error);
            Toastify({
                text: "Failed to create test paper. Please try again.",
                duration: 3000,
                gravity: "top",
                position: 'center',
                backgroundColor: "#e74c3c",
            }).showToast();
        } finally {
            setLoading(false); // Set loading to false
            clearForm(); // Clear form inputs
        }
        }
    };

    const clearForm = () => {
        setTitle('');
        setBatch('');
        setTestDate('');
        setSubject('');
        setQuestions([{ questionText: '', options: ['', '', '', ''], correctAnswer: '', marks: 1 }]);
    };

    const styles = {
        container: {
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            minHeight: '100vh',
            background: 'linear-gradient(to right, #6a11cb, #2575fc)',
            padding: '40px',
            borderRadius: '15px',
            boxShadow: '0 10px 30px rgba(0, 0, 0, 0.2)',
            color: '#fff',
            fontFamily: 'Arial, sans-serif',
        },
        header: {
            fontSize: '2.5em',
            marginBottom: '20px',
            textAlign: 'center',
            textShadow: '1px 1px 3px rgba(0, 0, 0, 0.3)',
        },
        form: {
            width: '100%',
            maxWidth: '600px',
            backgroundColor: '#fff',
            padding: '20px',
            borderRadius: '10px',
            boxShadow: '0 4px 20px rgba(0, 0, 0, 0.15)',
        },
        input: {
            width: '100%',
            padding: '12px',
            margin: '10px 0',
            borderRadius: '8px',
            border: '1px solid #ddd',
            transition: 'border-color 0.3s ease',
            fontSize: '1em',
        },
        questionBlock: {
            margin: '15px 0',
            padding: '15px',
            backgroundColor: '#f9f9f9',
            borderRadius: '8px',
            boxShadow: '0 2px 5px rgba(0, 0, 0, 0.1)',
            position: 'relative',
            transition: 'transform 0.2s ease',
        },
        deleteButton: {
            position: 'absolute',
            top: '10px',
            right: '10px',
            backgroundColor: '#e74c3c',
            color: 'white',
            border: 'none',
            borderRadius: '5px',
            cursor: 'pointer',
            padding: '6px 12px',
            fontSize: '0.8em',
        },
        button: {
            marginTop: '20px',
            padding: '12px 15px',
            backgroundColor: '#5a4d91',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            cursor: 'pointer',
            fontSize: '1.2em',
            transition: 'background-color 0.3s ease, transform 0.3s ease',
            boxShadow: '0 4px 8px rgba(0, 0, 0, 0.2)',
        },
        correctAnswerSelect: {
            margin: '10px 0',
            padding: '10px',
            borderRadius: '8px',
            border: '1px solid #ddd',
            width: '100%',
            fontSize: '1em',
        },
        batchSelect: {
            margin: '10px 0',
            padding: '10px',
            borderRadius: '8px',
            border: '1px solid #ddd',
            width: '100%',
            fontSize: '1em',
        },
    };

    return (
        <div style={styles.container}>
            <h1 style={styles.header}>Create Test Paper</h1>
            <form style={styles.form} onSubmit={handleSubmit}>
                <input
                    type="text"
                    placeholder="Test Title"
                    style={styles.input}
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                    required
                />
                <select
                    style={styles.batchSelect}
                    value={batch}
                    onChange={handleBatchChange}
                    required
                >
                    <option value="" disabled>Select Batch</option>
                    {batches.map((batchOption) => (
                        <option key={batchOption._id} value={batchOption._id}>
                            {batchOption.name} - {batchOption.standard.name}
                        </option>
                    ))}
                </select>
                <select
                    style={styles.input}
                    value={subject}
                    onChange={(e) => setSubject(e.target.value)}
                    required
                >
                    <option value="" disabled>Select Subject</option>
                    {subjects.map((subject, subjectIndex) => (
                        <option key={subjectIndex} value={subject}>
                            {subject}
                        </option>
                    ))}
                </select>

                <label htmlFor="testDate">Exam Date</label> {/* Label for exam date */}
                <input
                    type="date"
                    id="testDate"
                    style={styles.input}
                    value={testDate}
                    onChange={(e) => setTestDate(e.target.value)}
                    required
                />

                {questions.map((question, questionIndex) => (
                    <div key={questionIndex} style={styles.questionBlock}>
                        <input
                            type="text"
                            placeholder={`Question ${questionIndex + 1}`}
                            style={styles.input}
                            value={question.questionText}
                            onChange={(e) => handleQuestionChange(questionIndex, e)}
                            required
                        />

                        {question.options.map((option, optionIndex) => (
                            <input
                                key={optionIndex}
                                type="text"
                                placeholder={`Option ${optionIndex + 1}`}
                                style={styles.input}
                                value={option}
                                onChange={(e) => handleOptionChange(questionIndex, optionIndex, e)}
                                required
                            />
                        ))}
                        <select
                            style={styles.correctAnswerSelect}
                            value={question.correctAnswer}
                            onChange={(e) => handleCorrectAnswerChange(questionIndex, e)}
                            required
                        >
                            <option value="" disabled>Select Correct Answer</option>
                            {question.options.map((option, optionIndex) => (
                                <option key={optionIndex} value={optionIndex}>
                                    {`Option ${optionIndex + 1}: ${option}`}
                                </option>
                            ))}
                        </select>
                        <input
                            type="number"
                            placeholder="Marks"
                            style={styles.input}
                            value={question.marks}
                            onChange={(e) => handleMarksChange(questionIndex, e)}
                            required
                        />
                        <button
                            type="button"
                            style={styles.deleteButton}
                            onClick={() => deleteQuestion(questionIndex)}
                        >
                            Delete Question
                        </button>
                    </div>
                ))}

                <button type="button" style={styles.button} onClick={addQuestion}>
                    Add Question
                </button>
                &nbsp;&nbsp;    
                <button type="submit" style={styles.button} disabled={loading}>
                    {loading ? 'Submitting...' : 'Submit'}
                </button>
            </form>
        </div>
    );
}

export default TestPaperForm;
