import React, { useState } from 'react';
import { useGlobal } from '../context/GlobalContext';
import { Link } from 'react-router-dom';

const Header = () => {
  const {
    //  darkMode, 
    // toggleDarkMode, 
    toggleSidebar } = useGlobal();
  const [isSearchVisible, setIsSearchVisible] = useState(false);

  const handleSearchClick = () => setIsSearchVisible(!isSearchVisible);
  return (
    <header className="header">
      <section className="flex">
        <Link to="/Loggedin/" className="logo">Ex</Link>
        
        {/* Toggle visibility of search form on mobile */}
        <form 
          action="search.html" 
          method="post" 
          className={`search-form ${isSearchVisible ? 'visible' : ''}`}>
          <input type="text" name="search_box" required placeholder="search courses..." maxLength="100" />
          <button type="submit" className="fas fa-search"></button>
        </form>
        
        <div className="icons">
          <div id="menu-btn" className="fas fa-bars" onClick={toggleSidebar}></div>
          <div id="search-btn" className="fas fa-search" onClick={handleSearchClick}></div>
         <Link to="/loggedin/myprofile">
         <div id="user-btn" className="fas fa-user"></div>
         </Link> 
          {/* <div id="toggle-btn" className={`fas ${darkMode ? 'fa-moon' : 'fa-sun'}`} onClick={toggleDarkMode}></div> */}
        </div>
      </section>
    </header>
  );
};

export default Header;
